test('saved SDPA authenticates its exact historical artifact and sanitizes its actual policy hardware probe',async()=>{
 const source={artifactId:'12701291893',artifactName:'original',artifactBytes:123,artifactSha256:'d'.repeat(64),runId:'40428788379',toolingSha:'a6320337e843ea5234580bb0285f278470f63bfc'},artifact={id:12701291893,name:'original',size_in_bytes:123,digest:'sha256:'+'d'.repeat(64),expired:false,workflow_run:{id:40428788379,head_sha:source.toolingSha}};sdpaArtifact(artifact,source);for(const patch of [{id:1},{expired:true},{digest:'sha256:'+'0'.repeat(64)},{workflow_run:{id:1,head_sha:source.toolingSha}}])assert.throws(()=>sdpaArtifact({...artifact,...patch},source));
 const calls=[],probe=async(command,args,options)=>{calls.push({command,args,options});return {stdout:command.endsWith('ioreg')?'"IOPlatformUUID" = "D299B954-4C63-5322-86A5-BD5667051634"\nSERIAL_MUST_NOT_ARCHIVE':JSON.stringify({SPDisplaysDataType:[{_name:'Apple M5 Max',spdisplays_mtlgpufamilysupport:'spdisplays_metal4',serial:'SERIAL_MUST_NOT_ARCHIVE'}]})};};const host=await sdpaHost(probe);assert.equal(host.uuid,'D299B954-4C63-5322-86A5-BD5667051634');assert.doesNotMatch(JSON.stringify(host),/SERIAL_MUST/);assert.deepEqual(calls.map(x=>x.command),['/usr/sbin/ioreg','/usr/sbin/system_profiler']);assert.ok(calls.every(x=>x.options.timeout===10000&&x.options.maxBuffer<=512*1024));
 await assert.rejects(()=>sdpaHost(async(command,...args)=>({stdout:command.endsWith('ioreg')?'"IOPlatformUUID" = "WRONG"':(await probe(command,...args)).stdout})),/policy Mac/);
 await assert.rejects(()=>sdpaHost(async()=>{throw Object.assign(Error('SERIAL_MUST_NOT_ARCHIVE'),{stdout:'SERIAL_MUST_NOT_ARCHIVE'});}),error=>error.message==='saved SDPA bounded hardware metadata unavailable'&&!Object.hasOwn(error,'stdout'));
});
